def _parse(version):
    """Parse a SemVer string into (major, minor, patch, prerelease)."""
    without_build = version.split('+', 1)[0]

    if '-' in without_build:
        core, prerelease = without_build.split('-', 1)
        pre = prerelease.split('.')
    else:
        core = without_build
        pre = None

    major, minor, patch = (int(part) for part in core.split('.'))
    return major, minor, patch, pre


def _compare_prerelease(left, right):
    """Compare two prerelease identifier lists according to SemVer precedence."""
    for left_id, right_id in zip(left, right):
        left_numeric = left_id.isdigit()
        right_numeric = right_id.isdigit()

        if left_numeric and right_numeric:
            left_value = int(left_id)
            right_value = int(right_id)
            if left_value != right_value:
                return -1 if left_value < right_value else 1
        elif left_numeric != right_numeric:
            # Numeric identifiers always have lower precedence than alphanumeric.
            return -1 if left_numeric else 1
        elif left_id != right_id:
            return -1 if left_id < right_id else 1

    if len(left) != len(right):
        return -1 if len(left) < len(right) else 1
    return 0


def _compare_versions(left, right):
    left_major, left_minor, left_patch, left_pre = _parse(left)
    right_major, right_minor, right_patch, right_pre = _parse(right)

    left_core = (left_major, left_minor, left_patch)
    right_core = (right_major, right_minor, right_patch)
    if left_core != right_core:
        return -1 if left_core < right_core else 1

    if left_pre is None and right_pre is None:
        return 0
    if left_pre is None:
        return 1
    if right_pre is None:
        return -1

    return _compare_prerelease(left_pre, right_pre)


def sort_versions(vs):
    """Return semantic versions sorted by SemVer 2.0.0 precedence, stably."""
    return sorted(vs, key=cmp_to_key(_compare_versions))
